'use strict';

var Linter = require( 'eslint' ).Linter;
var rule = require( './../lib' );

var linter = new Linter();
var result;
var code;

// Generate our source code:
code = [
	'/**',
	'* Squares a number.',
	'*',
	'* Input | Output',
	'* ----- | ------',
	'* 2     | 4',
	'*',
	'* @param {number} x - input value',
	'* @returns {number} output value',
	'*',
	'* @example',
	'* var out = square( 2 );',
	'* // returns 4',
	'*/',
	'function square( x ) {',
	'\treturn x*x;',
	'}'
].join( '\n' );

// Lint the code:
result = linter.verify( code, {
	'plugins': {
		'stdlib': {
			'rules': {
				'jsdoc-table-pipes': rule
			}
		}
	},
	'rules': {
		'stdlib/jsdoc-table-pipes': 'error'
	}
});
console.log( result );
